package main

// Contract files: for each operation, the operation and everything it references, cut
// unchanged from the specification, so that an agent can read the full contract of the
// operations it uses without reading the whole specification.

import (
	"bytes"
	"fmt"
	"net/url"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

// Every generated file starts with this, which is how stale ones are recognized.
const generatedMarker = "<!-- Generated by openapi-reference"

const generatedComment = generatedMarker + " from the OpenAPI specification. Do not edit:\n" +
	"     it is regenerated whenever the specification changes. -->\n"

var unsafeFileChars = regexp.MustCompile(`[^A-Za-z0-9._-]`)

// The name of an operation's contract file.
func contractFile(id string) string {
	return unsafeFileChars.ReplaceAllString(id, "_") + ".md"
}

// The contract file for each operation that has an operationId, keyed by file name.
func contracts(root *yaml.Node, spec map[string]any, specURL string) (map[string]string, []string) {
	var warnings []string
	warn := func(format string, args ...any) { warnings = append(warnings, fmt.Sprintf(format, args...)) }

	version, _ := spec["openapi"].(string)
	info, _ := spec["info"].(map[string]any)
	title, _ := info["title"].(string)
	apiVersion := fmt.Sprint(info["version"])

	files := map[string]string{}
	owner := map[string]string{} // file name → operationId, to catch two that sanitize alike
	paths := mapGet(root, "paths")
	for _, path := range sortedNodeKeys(paths) {
		if !strings.HasPrefix(path, "/") {
			continue
		}
		item := mapGet(paths, path)
		var shared *yaml.Node // the path item a $ref beside these fields points to
		if ref := scalarAt(item, "$ref"); ref != "" {
			shared, _, _ = nodeAt(root, ref)
		}
		for _, method := range methods {
			op := mapGet(item, method)
			params := mapGet(item, "parameters")
			if op == nil && shared != nil {
				op = mapGet(shared, method)
			}
			if params == nil && shared != nil {
				params = mapGet(shared, "parameters")
			}
			id := scalarAt(op, "operationId")
			if op == nil || id == "" {
				continue
			}
			name := contractFile(id)
			if other, taken := owner[name]; taken {
				warn("%s and %s would both be written to %s; %s is skipped", other, id, name, id)
				continue
			}
			owner[name] = id

			text, problems := contractYAML(root, version, path, method, params, op)
			for _, problem := range problems {
				warn("%s: %s", id, problem)
			}
			summary := oneLine(scalarAt(op, "summary"))
			files[name] = contractPage(id, method, path, summary, title, apiVersion, specURL, text)
		}
	}
	return files, warnings
}

// One operation's contract as YAML: its path's parameters, the operation, and every node they
// reference, directly or indirectly, each placed where it is in the specification.
func contractYAML(root *yaml.Node, version, path, method string, params, op *yaml.Node) (string, []string) {
	var problems []string
	item := newMapping()
	if params != nil {
		setKey(item, "parameters", clone(params, 0))
	}
	setKey(item, method, clone(op, 0))
	paths := newMapping()
	setKey(paths, path, item)
	fragment := newMapping()
	setKey(fragment, "openapi", &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: version})
	setKey(fragment, "paths", paths)

	// Collect every local reference reachable from the operation, then copy each target in,
	// in pointer order so the result doesn't depend on discovery order.
	targets := map[string]*yaml.Node{}
	queue := collectRefs(nil, params)
	queue = collectRefs(queue, op)
	for len(queue) > 0 {
		ref := queue[0]
		queue = queue[1:]
		if _, done := targets[ref]; done {
			continue
		}
		node, viaSequence, ok := nodeAt(root, ref)
		if !ok {
			targets[ref] = nil // checkReferences reports it
			continue
		}
		if viaSequence {
			problems = append(problems, fmt.Sprintf("the reference %q points inside a list, so its target is not copied", ref))
			targets[ref] = nil
			continue
		}
		targets[ref] = node
		queue = collectRefs(queue, node)
	}
	refs := make([]string, 0, len(targets))
	for ref, node := range targets {
		if node != nil {
			refs = append(refs, ref)
		}
	}
	sort.Strings(refs)
	for _, ref := range refs {
		if !insertAt(fragment, pointerTokens(ref), clone(targets[ref], 0)) {
			problems = append(problems, fmt.Sprintf("the target of %q could not be placed", ref))
		}
	}

	var buf bytes.Buffer
	encoder := yaml.NewEncoder(&buf)
	encoder.SetIndent(2)
	if err := encoder.Encode(fragment); err != nil {
		problems = append(problems, err.Error())
	}
	encoder.Close()
	return buf.String(), problems
}

// The Markdown page for one operation's contract.
func contractPage(id, method, path, summary, title, version, specURL, contract string) string {
	spec := "the OpenAPI specification"
	if specURL != "" {
		spec = "[the OpenAPI specification](" + specURL + ")"
	}
	line := "`" + strings.ToUpper(method) + " " + path + "`"
	if summary != "" {
		line += ": " + summary
	}
	intro := fmt.Sprintf("This operation's complete contract, taken unchanged from %s (%s %s): its"+
		" path's parameters, the operation, and every component they reference, directly or"+
		" indirectly. If this file and the specification ever disagree, the specification is right.",
		spec, title, version)
	fence := strings.Repeat("`", max(3, longestRun(contract, '`')+1))

	var b strings.Builder
	fmt.Fprintf(&b, "# %s\n\n", id)
	b.WriteString(generatedComment + "\n")
	b.WriteString(line + "\n\n")
	b.WriteString(wrap(intro, 90) + "\n\n")
	b.WriteString(fence + "yaml\n" + contract + fence + "\n")
	return b.String()
}

// Write the contract files into dir, leaving files that are unchanged alone, and remove
// generated files there that no longer belong to an operation.
func writeContracts(dir string, files map[string]string) error {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	for name, content := range files {
		path := filepath.Join(dir, name)
		if existing, err := os.ReadFile(path); err == nil && string(existing) == content {
			continue
		}
		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
			return err
		}
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return err
	}
	for _, entry := range entries {
		if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".md") {
			continue
		}
		if _, current := files[entry.Name()]; current {
			continue
		}
		path := filepath.Join(dir, entry.Name())
		content, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		if bytes.Contains(content[:min(len(content), 512)], []byte(generatedMarker)) {
			if err := os.Remove(path); err != nil {
				return err
			}
		}
	}
	return nil
}

// Add the local references in a node and everything under it to queue.
func collectRefs(queue []string, n *yaml.Node) []string {
	n = deref(n)
	if n == nil {
		return queue
	}
	if n.Kind == yaml.MappingNode {
		for i := 0; i+1 < len(n.Content); i += 2 {
			key, value := n.Content[i], deref(n.Content[i+1])
			if key.Value == "$ref" && value != nil && value.Kind == yaml.ScalarNode && strings.HasPrefix(value.Value, "#/") {
				queue = append(queue, value.Value)
			}
		}
	}
	for _, child := range n.Content {
		queue = collectRefs(queue, child)
	}
	return queue
}

// The node a local JSON Pointer reference names, and whether reaching it went through a list.
func nodeAt(root *yaml.Node, ref string) (*yaml.Node, bool, bool) {
	if !strings.HasPrefix(ref, "#/") {
		return nil, false, false
	}
	n, viaSequence := root, false
	for _, token := range pointerTokens(ref) {
		n = deref(n)
		switch {
		case n == nil:
			return nil, false, false
		case n.Kind == yaml.MappingNode:
			if n = mapGet(n, token); n == nil {
				return nil, false, false
			}
		case n.Kind == yaml.SequenceNode:
			i, err := strconv.Atoi(token)
			if err != nil || i < 0 || i >= len(n.Content) {
				return nil, false, false
			}
			n, viaSequence = n.Content[i], true
		default:
			return nil, false, false
		}
	}
	return deref(n), viaSequence, true
}

// A JSON Pointer's tokens, percent-decoded as a URI fragment's are, then ~1 and ~0 decoded.
func pointerTokens(ref string) []string {
	tokens := strings.Split(strings.TrimPrefix(ref, "#/"), "/")
	for i, token := range tokens {
		if unescaped, err := url.PathUnescape(token); err == nil {
			token = unescaped
		}
		tokens[i] = strings.ReplaceAll(strings.ReplaceAll(token, "~1", "/"), "~0", "~")
	}
	return tokens
}

// Place value at the path tokens name within fragment, creating mappings on the way. It
// reports false if something other than a mapping is in the way.
func insertAt(fragment *yaml.Node, tokens []string, value *yaml.Node) bool {
	n := fragment
	for i, token := range tokens {
		child := mapGet(n, token)
		if i == len(tokens)-1 {
			if child == nil {
				setKey(n, token, value)
			}
			return true // already present: the same node, copied once
		}
		if child == nil {
			child = newMapping()
			setKey(n, token, child)
		} else if child.Kind != yaml.MappingNode {
			return false
		}
		n = child
	}
	return true
}

// A deep copy, with aliases replaced by copies of what they refer to and anchors removed, so
// the copy stands alone.
func clone(n *yaml.Node, depth int) *yaml.Node {
	n = deref(n)
	if n == nil || depth > 10000 {
		return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!null", Value: "null"}
	}
	copied := *n
	copied.Anchor = ""
	copied.Content = nil
	for _, child := range n.Content {
		copied.Content = append(copied.Content, clone(child, depth+1))
	}
	return &copied
}

func deref(n *yaml.Node) *yaml.Node {
	for i := 0; n != nil && n.Kind == yaml.AliasNode && i < 100; i++ {
		n = n.Alias
	}
	if n != nil && n.Kind == yaml.DocumentNode && len(n.Content) > 0 {
		n = n.Content[0]
	}
	return n
}

func mapGet(n *yaml.Node, key string) *yaml.Node {
	n = deref(n)
	if n == nil || n.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i+1 < len(n.Content); i += 2 {
		if n.Content[i].Value == key {
			return n.Content[i+1]
		}
	}
	return nil
}

func scalarAt(n *yaml.Node, key string) string {
	if v := deref(mapGet(n, key)); v != nil && v.Kind == yaml.ScalarNode {
		return v.Value
	}
	return ""
}

func sortedNodeKeys(n *yaml.Node) []string {
	n = deref(n)
	var keys []string
	if n != nil && n.Kind == yaml.MappingNode {
		for i := 0; i+1 < len(n.Content); i += 2 {
			keys = append(keys, n.Content[i].Value)
		}
	}
	sort.Strings(keys)
	return keys
}

func newMapping() *yaml.Node {
	return &yaml.Node{Kind: yaml.MappingNode, Tag: "!!map"}
}

func setKey(m *yaml.Node, key string, value *yaml.Node) {
	m.Content = append(m.Content, &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: key}, value)
}

// The longest run of c in s.
func longestRun(s string, c byte) int {
	longest, run := 0, 0
	for i := 0; i < len(s); i++ {
		if s[i] == c {
			run++
			longest = max(longest, run)
		} else {
			run = 0
		}
	}
	return longest
}
